def icon_data(color: str, size: int = 32) -> dict:
    """
    Arma el diccionario que pydeck necesita para dibujar un ícono de pin
    (en vez del círculo plano de antes) en la posición de cada fila.
    "color" es una de las claves de _PINES_B64 (morado, azul_claro,
    naranja, rojo, azul_repetido, gris). "size" es el alto en pixeles
    con el que se dibuja el pin en el mapa (el ancho se ajusta solo,
    según la proporción real de la imagen).
    """
    return {
        "url": f"data:image/png;base64,{_PINES_B64[color]}",
        "width": ICONO_ANCHO,
        "height": ICONO_ALTO,
        "anchorY": ICONO_ANCHOR_Y,
    }
